package items_test

import (
	"errors"
	"testing"

	"github.com/mbashem/cftracker/backend/configs"
	"github.com/mbashem/cftracker/backend/internal/lists/items"
)

// Verify request validation is independent of order loading and position calculation.
// Generated by Codex and not thoroughly checked for correctness.
func TestMoveValidation(t *testing.T) {
	a, b := "A", "B"
	for _, tc := range []struct {
		name  string
		move  items.Move
		valid bool
	}{
		{"group before anchor", items.Move{ProblemIDs: []string{a, "C"}, Before: &b}, true},
		{"single after anchor", items.Move{ProblemIDs: []string{a}, After: &b}, true},
		{"opaque keys and exact matching", items.Move{ProblemIDs: []string{"judge:opaque:key", " A "}, Before: &a}, true},
		{"append", items.Move{ProblemIDs: []string{a}}, true},
		{"empty selection", items.Move{}, false},
		{"oversized selection", items.Move{ProblemIDs: make([]string, configs.MaxItemsPerList+1)}, false},
		{"empty ID", items.Move{ProblemIDs: []string{""}}, false},
		{"duplicate ID", items.Move{ProblemIDs: []string{a, a}}, false},
		{"anchor in selection", items.Move{ProblemIDs: []string{a, b}, Before: &b}, false},
		{"two anchors", items.Move{ProblemIDs: []string{a}, Before: &b, After: &b}, false},
	} {
		t.Run(tc.name, func(t *testing.T) {
			err := tc.move.Validate()
			if tc.valid && err != nil || !tc.valid && !errors.Is(err, items.ErrInvalidOperation) {
				t.Fatalf("%+v: %v", tc.move, err)
			}
		})
	}
}
